document.addEventListener('DOMContentLoaded', () => { initCartCounter(); initCategoryFilters(); initSearch(); initProductDetails(); initCartPage(); }); function getCart() { const cart = localStorage.getItem('modan_catalog_cart'); return cart ? JSON.parse(cart) : [ { id: 1, title: 'Шерстяной кардиган', price: 78, qty: 1, img: 'assets/cardigan.jpg' }, { id: 3, title: 'Пальто оверсайз', price: 99, qty: 1, img: 'assets/coat.jpg' } ]; } function saveCart(cart) { localStorage.setItem('modan_catalog_cart', JSON.stringify(cart)); updateCartBadge(); } function updateCartBadge() { const cart = getCart(); const totalQty = cart.reduce((sum, item) => sum + item.qty, 0); const badges = document.querySelectorAll('.cart-badge'); badges.forEach(b => b.textContent = totalQty); } function initCartCounter() { updateCartBadge(); } function showToast(message) { let toast = document.getElementById('toast'); if (!toast) { toast = document.createElement('div'); toast.id = 'toast'; toast.className = 'toast'; document.body.appendChild(toast); } toast.textContent = message; toast.classList.add('show'); setTimeout(() => { toast.classList.remove('show'); }, 2200); } function initCategoryFilters() { const filterCards = document.querySelectorAll('.category-card'); const productCards = document.querySelectorAll('.product-card'); if (filterCards.length > 0) { filterCards.forEach(card => { card.addEventListener('click', () => { filterCards.forEach(c => c.classList.remove('active')); card.classList.add('active'); const category = card.getAttribute('data-category'); productCards.forEach(pCard => { const cardCat = pCard.getAttribute('data-category'); if (category === 'all' || cardCat === category) { pCard.style.display = 'flex'; } else { pCard.style.display = 'none'; } }); }); }); } } function initSearch() { const searchInput = document.getElementById('searchInput'); const productCards = document.querySelectorAll('.product-card'); if (searchInput) { searchInput.addEventListener('input', (e) => { const query = e.target.value.toLowerCase().trim(); productCards.forEach(card => { const title = card.querySelector('.product-title').textContent.toLowerCase(); if (title.includes(query)) { card.style.display = 'flex'; } else { card.style.display = 'none'; } }); }); } } function initProductDetails() { const sizeBtns = document.querySelectorAll('.size-btn'); sizeBtns.forEach(btn => { btn.addEventListener('click', () => { sizeBtns.forEach(b => b.classList.remove('active')); btn.classList.add('active'); }); }); const addToCartBtn = document.getElementById('addToCartBtn'); if (addToCartBtn) { addToCartBtn.addEventListener('click', () => { const activeSize = document.querySelector('.size-btn.active')?.textContent || 'M'; const cart = getCart(); cart.push({ id: Date.now(), title: 'Пальто оверсайз', price: 99, size: activeSize, qty: 1, img: 'assets/coat.jpg' }); saveCart(cart); showToast(`Пальто оверсайз (${activeSize}) добавлено в корзину!`); }); } const wishlistBtns = document.querySelectorAll('.btn-wishlist'); wishlistBtns.forEach(btn => { btn.addEventListener('click', (e) => { e.stopPropagation(); if (btn.textContent === '♡') { btn.textContent = '♥'; btn.style.color = '#C47847'; showToast('Добавлено в Избранное'); } else { btn.textContent = '♡'; btn.style.color = 'var(--text-primary)'; } }); }); } function initCartPage() { const cartListContainer = document.getElementById('cartItemsList'); if (!cartListContainer) return; renderCartItems(); const checkoutForm = document.getElementById('checkoutForm'); if (checkoutForm) { checkoutForm.addEventListener('submit', (e) => { e.preventDefault(); const cart = getCart(); if (cart.length === 0) { showToast('Ваша корзина пуста!'); return; } showToast('Заказ успешно оформлен! Спасибо!'); saveCart([]); setTimeout(() => { renderCartItems(); }, 1000); }); } } function renderCartItems() { const cartListContainer = document.getElementById('cartItemsList'); if (!cartListContainer) return; const cart = getCart(); cartListContainer.innerHTML = ''; if (cart.length === 0) { cartListContainer.innerHTML = ` <div style="text-align: center; padding: 2.5rem 1rem; color: var(--text-secondary);"> <p style="font-size: 0.95rem; margin-bottom: 1rem;">Ваша корзина пуста</p> <a href="index.html" class="btn-primary" style="width: auto; display: inline-flex;">Перейти в каталог</a> </div> `; updateOrderSummary(0); return; } let totalSum = 0; cart.forEach((item, index) => { totalSum += item.price * item.qty; const itemEl = document.createElement('div'); itemEl.className = 'cart-item'; itemEl.innerHTML = ` <img src="${item.img || 'assets/coat.jpg'}" alt="${item.title}" class="cart-item-img"> <div class="cart-item-info"> <h4 style="font-size: 0.88rem; font-weight: 600;">${item.title}</h4> <p style="font-weight: 700; color: var(--accent-price); font-size: 0.9rem;">${item.price * item.qty} BYN</p> <div class="qty-control"> <button class="qty-btn" onclick="changeQty(${index}, -1)">-</button> <span style="font-size: 0.8rem; font-weight: 600;">${item.qty}</span> <button class="qty-btn" onclick="changeQty(${index}, 1)">+</button> </div> </div> <button onclick="removeCartItem(${index})" style="background: transparent; color: var(--text-muted); font-size: 1.1rem;" title="Удалить"> ✕ </button> `; cartListContainer.appendChild(itemEl); }); updateOrderSummary(totalSum); } window.changeQty = function(index, delta) { const cart = getCart(); if (cart[index]) { cart[index].qty += delta; if (cart[index].qty <= 0) { cart.splice(index, 1); } saveCart(cart); renderCartItems(); } }; window.removeCartItem = function(index) { const cart = getCart(); cart.splice(index, 1); saveCart(cart); renderCartItems(); showToast('Товар удален из корзины'); }; function updateOrderSummary(subtotal) { const subtotalEl = document.getElementById('summarySubtotal'); const deliveryEl = document.getElementById('summaryDelivery'); const totalEl = document.getElementById('summaryTotal'); const deliveryCost = subtotal > 0 ? (subtotal > 150 ? 0 : 7) : 0; const total = subtotal + deliveryCost; if (subtotalEl) subtotalEl.textContent = `${subtotal} BYN`; if (deliveryEl) deliveryEl.textContent = deliveryCost === 0 ? 'Бесплатно' : `${deliveryCost} BYN`; if (totalEl) totalEl.textContent = `${total} BYN`; }